public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null || nums.length == 0) return res;
    res.add(new java.util.ArrayList<>());
    for (int num : nums) {
        java.util.List<java.util.List<Integer>> newRes = new java.util.ArrayList<>();
        for (java.util.List<Integer> perm : res) {
            for (int i = 0; i <= perm.size(); i++) {
                java.util.List<Integer> newPerm = new java.util.ArrayList<>(perm);
                newPerm.add(i, num);
                newRes.add(newPerm);
            }
        }
        res = newRes;
    }
    java.util.Collections.reverse(res);
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    for (String s : strings) {
        if (s != null && s.length() > maxLen) {
            maxLen = s.length();
        }
    }
    // Build a set of all substrings from all strings
    Set<String> substrSet = new HashSet<>();
    for (String s : strings) {
        if (s == null) {
            continue;
        }
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                substrSet.add(s.substring(i, j));
            }
        }
    }
    // Search for the largest length where a substring or its reverse exists
    for (int l = maxLen; l >= 1; l--) {
        for (String sub : substrSet) {
            if (sub.length() != l) {
                continue;
            }
            String rev = new StringBuilder(sub).reverse().toString();
            if (substrSet.contains(rev)) {
                return l;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new boolean[grid[i].length];
    }
    int deposits = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
                            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

