public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num == 0) {
            // 0 is twice 0; count only if there is at least one more 0
            if (freq.get(0) > 1) {
                count++;
            }
        } else if (num % 2 == 0) {
            int half = num / 2;
            if (freq.containsKey(half)) {
                count++;
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    // If start equals end
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }
    // Build adjacency list
    int total = n * n;
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(total);
    for (int i = 0; i < total; i++) {
        adj.add(new java.util.ArrayList<>());
    }
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            int idx1 = x1 * n + y1;
            int idx2 = x2 * n + y2;
            // Ensure adjacency is undirected
            adj.get(idx1).add(idx2);
            adj.get(idx2).add(idx1);
        }
    }
    int startIdx = sx * n + sy;
    int endIdx = ex * n + ey;
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    boolean[] visited = new boolean[total];
    queue.offer(startIdx);
    visited[startIdx] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int nb : adj.get(cur)) {
            if (!visited[nb]) {
                if (nb == endIdx) {
                    return "can be travelled";
                }
                visited[nb] = true;
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

