public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fib.add(a);
    fib.add(b);
    while (true) {
        int c = a + b;
        if (c > k) {
            break;
        }
        fib.add(c);
        a = b;
        b = c;
    }

    // Greedy subtraction from the largest Fibonacci number
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if c and top are the same letter with opposite cases
            if (Math.abs(c - top) == 32) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(c); // push current character onto the stack
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null) {
        return 0;
    }
    int[] max = new int[1];
    backtrack(s, 0, new java.util.HashSet<>(), max);
    return max[0];
}

private void backtrack(String s, int index, java.util.Set<String> used, int[] max) {
    if (index == s.length()) {
        max[0] = Math.max(max[0], used.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            backtrack(s, end, used, max);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    int depth = 0;
    if (logs == null) {
        return 0;
    }
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("./")) {
            // stay in the current folder
            continue;
        } else if (log.equals("../")) {
            // move up one folder if possible
            if (depth > 0) {
                depth--;
            }
        } else {
            // assume any other string ending with '/' is a folder entry
            if (log.endsWith("/")) {
                depth++;
            }
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input: each character contributes at least 1 and at most 26
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    // Start with all 'a' (value 1)
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // extra value needed beyond all 'a's
    // Increase characters from the end to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

