public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high || high < 0) {
        return result;
    }
    if (low < 0) {
        low = 0;
    }

    java.util.TreeSet<Integer> resultSet = new java.util.TreeSet<>();
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    java.util.Set<Long> visited = new java.util.HashSet<>();

    for (int i = 0; i <= 9; i++) {
        long num = i;
        if (num > high) {
            continue;
        }
        if (num >= low) {
            resultSet.add((int) num);
        }
        queue.offer(num);
        visited.add(num);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        long lastDigit = num % 10;

        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high && !visited.contains(next)) {
                if (next >= low) {
                    resultSet.add((int) next);
                }
                queue.offer(next);
                visited.add(next);
            }
        }

        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high && !visited.contains(next)) {
                if (next >= low) {
                    resultSet.add((int) next);
                }
                queue.offer(next);
                visited.add(next);
            }
        }
    }

    return new ArrayList<>(resultSet);
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set.
    // Using the property that n & (n-1) clears the lowest set bit.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num > 9) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero directly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    int absValue = Math.abs(n);
    String numberStr = Integer.toString(absValue);

    StringBuilder reversed = new StringBuilder();
    int len = numberStr.length();

    // Build reversed string with dots inserted every three digits
    for (int i = 0; i < len; i++) {
        reversed.append(numberStr.charAt(len - 1 - i));
        // Insert dot after every three digits, except at the end
        if ((i + 1) % 3 == 0 && (i + 1) != len) {
            reversed.append('.');
        }
    }

    // Reverse back to original order
    String result = reversed.reverse().toString();

    // Prepend negative sign if needed
    if (negative) {
        result = "-" + result;
    }

    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    // Precompute which pairs can be adjacent
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                continue;
            }
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                can[i][j] = true;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    // Initialize dp for single-element permutations
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // Build up dp table
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) {
                continue;
            }
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) {
                    continue; // already used
                }
                if (can[last][next]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        if (h < 0) {
            h = 0; // treat negative heights as zero
        }
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        int start = Math.max(0, k - n + 1);
        int end = Math.min(k, m - 1);
        if ((k & 1) == 0) {
            for (int i = end; i >= start; i--) {
                int j = k - i;
                result[index++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = k - i;
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length must be positive");
    }
    return build(n, n);
}

private static List<String> build(int currentLen, int totalLen) {
    if (currentLen == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (currentLen == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> prev = build(currentLen - 2, totalLen);
    List<String> result = new ArrayList<>();
    for (String s : prev) {
        if (currentLen != totalLen) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check that each point has exactly two coordinates
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    // Compute the area of the triangle formed by the three points
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];
    int area2 = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long nextUglyLong = Math.min(next2, Math.min(next3, next5));
        int nextUgly = (int) nextUglyLong;
        ugly[i] = nextUgly;
        if (nextUglyLong == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2;
        }
        if (nextUglyLong == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3;
        }
        if (nextUglyLong == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    return Math.max(max, current);
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(c);
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}
